	protected Advertiser read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Advertiser" );

		Advertiser entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Advertiser with primary key" );
		msg.append( advertiserId );
		
		AdvertiserFetchOneSummary fetchOneSummary = new AdvertiserFetchOneSummary( advertiserId );

		try {
			entity = AdvertiserService.getAdvertiserInstance().getAdvertiser( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Advertiser " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Advertiser.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Advertiser." );

		StringBuilder msg = new StringBuilder( "Failed to update a Advertiser : " );        
		Advertiser entity = read();
		UpdateAdvertiserCommand command = generateUpdateCommand();
		command.setAdvertiserId(entity.getAdvertiserId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Advertiser." );

			// for use later on...
			advertiserId = entity.getAdvertiserId();

			AdvertiserService proxy = AdvertiserService.getAdvertiserInstance();  

			proxy.updateAdvertiser( command ).get();

			LOGGER.info( "-- Successfully saved Advertiser - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + advertiserId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Advertiser.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Advertiser." );

		Advertiser entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Advertiser with id " + advertiserId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Advertiser with id " + advertiserId );

			throw e;
		}

		try{
			AdvertiserService.getAdvertiserInstance().delete( new DeleteAdvertiserCommand( entity.getAdvertiserId() ) ).get();
			LOGGER.info( "-- Successfully deleted Advertiser with id " + advertiserId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Advertiser with id " + advertiserId );

			throw e;
		}
	}

	/**
	 * get all Advertisers.
	 */
	protected List<Advertiser> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Advertisers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Advertiser : " );        
		List<Advertiser> collection  = new ArrayList<>();

		try {
			// call the static get method on the AdvertiserService
			collection = AdvertiserService.getAdvertiserInstance().getAllAdvertiser();
			assertNotNull( collection, "An Empty collection of Advertiser was incorrectly returned.");
			
			// Now print out the values
			Advertiser entity = null;            
			Iterator<Advertiser> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getAdvertiserId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

